//! What ODS says about each op: its traits, its interfaces, and its memory effects.
//!
//! Nothing here is global: the ops and dialects a context knows are kept in an [`OpInfos`]
//! (the upstream rows by `traits.gen.rs`, generated by `scripts/traits.py`; a loaded dialect
//! brings its own), and users ask the context ([`MlirOpt`](crate::MlirOpt)). An op it does not
//! know (unregistered, or a dialect outside the table) has no traits and unknown effects, as
//! `mlir-opt` treats it.

use alloc::collections::{BTreeMap, BTreeSet};
use alloc::vec::Vec;

/// Declares [`Trait`]: one variant per native trait and interface name found in ODS.
macro_rules! traits {
    ($($t:ident,)*) => {
        /// A native op trait (`IsTerminator`, `IsIsolatedFromAbove`, …) or an op interface
        /// (`SymbolOpInterface`, `MemoryEffectOpInterface`, …), by its C++ name.
        #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
        #[allow(non_camel_case_types)]
        pub enum Trait { $($t),* }
    };
}

#[path = "traits.gen.rs"]
mod table;

pub use table::Trait;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EffectKind {
    Read,
    Write,
    Allocate,
    Free,
}

/// What an effect is on: the op as a whole, or one ODS operand / result group.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EffectOn {
    Op,
    Operand(u32),
    Result(u32),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Effect {
    pub kind: EffectKind,
    pub on: EffectOn,
    /// The C++ resource name, e.g. `DefaultResource`, `AutomaticAllocationScopeResource`.
    pub resource: &'static str,
}

/// An op's memory effects.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Effects {
    /// The op declares nothing: anything may happen.
    Unknown,
    /// Exactly these (empty: none at all). Nested ops add theirs when the op has
    /// [`Trait::HasRecursiveMemoryEffects`].
    Known(&'static [Effect]),
    /// The op computes them in C++ (`getEffects`); see the pass framework (mlirpass's `effects_of`).
    Custom,
}

/// One op's row.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct OpInfo {
    pub name: &'static str,
    pub traits: &'static [Trait],
    pub effects: Effects,
    /// The attributes and properties ODS declares: they live in `<{...}>`, the rest in `{...}`.
    pub inherent: &'static [&'static str],
}

impl OpInfo {
    pub fn has(&self, t: Trait) -> bool {
        self.traits.contains(&t)
    }
}

/// ODS facts by op name, and the namespaces they belong to: the data a context
/// ([`MlirOpt`](crate::MlirOpt)) answers from.
#[derive(Debug, Clone, Default)]
pub struct OpInfos {
    ops: BTreeMap<&'static str, OpInfo>,
    dialects: BTreeSet<&'static str>,
}

impl OpInfos {
    /// Knows nothing.
    pub const fn new() -> Self {
        Self { ops: BTreeMap::new(), dialects: BTreeSet::new() }
    }

    /// What `mlir-opt` 22.1.8 knows: every upstream op, and the dialects it registers
    /// (`mlir-opt --show-dialects`).
    pub fn upstream() -> Self {
        let mut infos = Self::new();
        infos.register_upstream_ops();
        for ns in [
            "acc", "affine", "amdgpu", "amx", "arith", "arm_neon", "arm_sme", "arm_sve", "async", "bufferization", "builtin", "cf", "complex", "dlti", "emitc", "func", "gpu", "index", "irdl", "linalg", "llvm", "math", "memref", "ml_program", "mpi", "nvgpu", "nvvm", "omp", "pdl", "pdl_interp", "ptr", "quant", "rocdl", "scf", "shape", "shard", "smt", "sparse_tensor", "spirv", "tensor", "test", "test_dyn", "test_irdl_to_cpp", "tosa", "transform", "ub", "vector", "wasmssa", "x86vector", "xegpu", "xevm",
        ] {
            infos.dialect(ns);
        }
        infos
    }

    /// Registers (or replaces) an op's row.
    pub fn insert(&mut self, info: OpInfo) {
        self.ops.insert(info.name, info);
    }

    /// The rows of dialect `ns`'s ops.
    pub fn of_dialect(&self, ns: &str) -> Vec<OpInfo> {
        self.ops.values().filter(|i| i.name.split_once('.').is_some_and(|(d, _)| d == ns)).copied().collect()
    }

    /// Registers a dialect name.
    pub fn dialect(&mut self, ns: &'static str) {
        self.dialects.insert(ns);
    }

    /// The row for op `name`.
    pub fn op_info(&self, name: &str) -> Option<&OpInfo> {
        self.ops.get(name)
    }

    /// Whether namespace `ns` is known.
    pub fn knows_dialect(&self, ns: &str) -> bool {
        self.dialects.contains(ns)
    }
}
